create schema if not exists finance;

-- CONFIRMED: checked all tracked statements in 0001-0008 this session — none
-- create these enum types. Not commented out; required for a fresh instance.
do $$ begin
  create type public.payment_method as enum (
    'upi','credit_card','debit_card','net_banking','cash','cheque',
    'demand_draft','scholarship','grant','loan','waiver'
  );
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.payment_status as enum (
    'pending','processing','success','failed','refunded'
  );
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.payout_status as enum (
    'draft','pending_approval','approved','paid','rejected'
  );
exception when duplicate_object then null; end $$;


-- ============================================================================
-- 1. vendors
-- ============================================================================
create table finance.vendors (
  id            uuid primary key default gen_random_uuid(),
  school_id     uuid not null references public.schools(id) on delete cascade,
  name          text not null,
  contact_info  text,
  created_at    timestamptz not null default now(),
  gstin         text
);
create index idx_vendors_school_id on finance.vendors(school_id);

alter table finance.vendors enable row level security;

create policy admin_insert_vendors on finance.vendors
for insert
with check (((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = any (array['admin','principal']));

-- FIXED (was broken: root-level auth.jwt() ->> 'school_id' claim doesn't exist)
create policy school_isolation_select_vendors on finance.vendors
for select
using (school_id = (((auth.jwt() -> 'app_metadata'::text) ->> 'school_id'::text))::uuid);


