  academic_year  text not null,
  created_at     timestamptz not null default now()
);
create index idx_fee_structures_school_id on finance.fee_structures(school_id);

alter table finance.fee_structures enable row level security;

-- FIXED (was broken: root-level auth.jwt() ->> 'school_id' claim doesn't exist)
create policy school_isolation_select_fee_structures on finance.fee_structures
for select
using (school_id = (((auth.jwt() -> 'app_metadata'::text) ->> 'school_id'::text))::uuid);


-- ============================================================================
-- 3. invoices
-- ============================================================================
create table finance.invoices (
  id                    uuid primary key default gen_random_uuid(),
  student_id            uuid not null references public.students(id) on delete cascade,
  fee_structure_id      uuid not null references finance.fee_structures(id),
  amount_due            numeric(12,2) not null check (amount_due >= 0),
  amount_paid           numeric(12,2) not null default 0 check (amount_paid >= 0),
  due_date              date not null,
  created_at            timestamptz not null default now(),
  gst_rate              numeric default 0 check (gst_rate >= 0),
  gst_amount            numeric default 0 check (gst_amount >= 0),
  invoice_number        text,
  late_fee_applied_at   timestamptz
);
create index idx_invoices_student on finance.invoices(student_id);
create index idx_invoices_fee_structure_id on finance.invoices(fee_structure_id);

alter table finance.invoices enable row level security;

create policy admin_insert_invoices on finance.invoices
for insert
with check (((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = any (array['admin','principal']));

create policy school_isolation_select_invoices on finance.invoices
for select
using (
  exists (
    select 1 from students s
    where s.id = invoices.student_id
      and s.school_id = (((auth.jwt() -> 'app_metadata'::text) ->> 'school_id'::text))::uuid
  )
);

create policy admin_update_invoices on finance.invoices
for update
using (((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = any (array['admin','principal']))
with check (((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = any (array['admin','principal']));

create trigger audit_invoices
after insert or update or delete on finance.invoices
for each row execute function audit.log_change();


-- ============================================================================
-- 4. payments
-- ============================================================================
create table finance.payments (
  id                     uuid primary key default gen_random_uuid(),
  invoice_id             uuid not null references finance.invoices(id) on delete cascade,
  amount                 numeric(12,2) not null check (amount > 0),
  method                 public.payment_method not null,
  status                 public.payment_status not null default 'pending',
  gateway_order_id       text,
  gateway_payment_id     text,
  gateway_signature      text,
  raw_gateway_response   jsonb,
  approved_by            uuid references public.staff(id),
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  reference_number       text
);
create index idx_payments_invoice on finance.payments(invoice_id);
create index idx_payments_status on finance.payments(status);
create index idx_payments_approved_by on finance.payments(approved_by);

alter table finance.payments enable row level security;

-- NOTE: admin_insert_payments was fixed earlier this session (previously missing
-- an INSERT policy entirely — was the root cause of the "Offline Payment Entry"
-- RLS error). Included here already-fixed.
create policy admin_insert_payments on finance.payments
for insert
with check (
  ((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = any (array['admin','principal'])
  and exists (
    select 1 from finance.invoices i
    join students s on s.id = i.student_id
    where i.id = payments.invoice_id
      and s.school_id = (((auth.jwt() -> 'app_metadata'::text) ->> 'school_id'::text))::uuid
  )
);

create policy school_isolation_select_payments on finance.payments
for select
using (
  exists (
    select 1 from finance.invoices i
    join students s on s.id = i.student_id
    where i.id = payments.invoice_id
      and s.school_id = (((auth.jwt() -> 'app_metadata'::text) ->> 'school_id'::text))::uuid
  )
);

create trigger audit_payments
after insert or update or delete on finance.payments
for each row execute function audit.log_change();

create trigger trg_payments_updated_at
before update on finance.payments
for each row execute function public.set_updated_at();


