-- ============================================================================
-- 11. waiver_requests
-- ============================================================================
create table finance.waiver_requests (
  id                 uuid primary key default gen_random_uuid(),
  student_id         uuid not null references public.students(id),
  invoice_id         uuid references finance.invoices(id),
  request_type       text not null check (request_type = any (array['scholarship','waiver','grant'])),
  requested_amount   numeric not null check (requested_amount > 0),
  reason             text,
  status             text not null default 'pending'
                       check (status = any (array['pending','approved','rejected'])),
  approved_by        uuid references public.staff(id),
  created_at         timestamptz not null default now(),
  disbursed_at       timestamptz
);
create index idx_waivers_student_id on finance.waiver_requests(student_id);
create index idx_waivers_invoice_id on finance.waiver_requests(invoice_id);
create index idx_waivers_approved_by on finance.waiver_requests(approved_by);

alter table finance.waiver_requests enable row level security;

create policy parent_insert_waiver_requests on finance.waiver_requests
for insert
with check (
  student_id in (select parent_links.student_id from parent_links where parent_links.parent_auth_user_id = auth.uid())
  or ((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = any (array['admin','principal'])
);

create policy waiver_requests_read on finance.waiver_requests
for select
using (
  ((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = any (array['admin','principal'])
  or student_id in (select parent_links.student_id from parent_links where parent_links.parent_auth_user_id = auth.uid())
  or student_id in (select students.id from students where students.auth_user_id = auth.uid())
);

create policy admin_decide_waiver_requests on finance.waiver_requests
for update
using (((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = any (array['admin','principal']))
with check (((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = any (array['admin','principal']));


-- ============================================================================
-- 12. payment_plans
-- ============================================================================
create table finance.payment_plans (
  id                    uuid primary key default gen_random_uuid(),
  invoice_id            uuid not null references finance.invoices(id),
  total_installments     integer not null check (total_installments > 1),
  installment_amount    numeric not null check (installment_amount > 0),
  start_date            date not null,
  status                text not null default 'active'
                          check (status = any (array['active','completed','defaulted','cancelled'])),
  created_at            timestamptz not null default now()
);
create index idx_payment_plans_invoice_id on finance.payment_plans(invoice_id);

alter table finance.payment_plans enable row level security;

create policy admin_insert_payment_plans on finance.payment_plans
for insert
with check (((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = any (array['admin','principal']));

create policy parent_request_payment_plans on finance.payment_plans
for insert
with check (
  invoice_id in (
    select i.id from finance.invoices i
    join parent_links pl on pl.student_id = i.student_id
    where pl.parent_auth_user_id = auth.uid()
  )
);

create policy payment_plans_read on finance.payment_plans
for select
using (
  ((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = any (array['admin','principal'])
  or invoice_id in (
    select i.id from finance.invoices i
    where i.student_id in (select students.id from students where students.auth_user_id = auth.uid())
       or i.student_id in (select parent_links.student_id from parent_links where parent_links.parent_auth_user_id = auth.uid())
  )
);


-- ============================================================================
-- 13. payment_plan_installments
-- ============================================================================
create table finance.payment_plan_installments (
  id                   uuid primary key default gen_random_uuid(),
  payment_plan_id      uuid not null references finance.payment_plans(id),
  installment_number   integer not null,
  due_date             date not null,
  amount               numeric not null check (amount > 0),
  status               text not null default 'pending'
                         check (status = any (array['pending','paid','overdue'])),
  payment_id           uuid references finance.payments(id),
  unique (payment_plan_id, installment_number)
);
create index idx_installments_payment_id on finance.payment_plan_installments(payment_id);

alter table finance.payment_plan_installments enable row level security;

create policy admin_insert_installments on finance.payment_plan_installments
for insert
with check (((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = any (array['admin','principal']));

create policy installments_read on finance.payment_plan_installments
for select
using (
  ((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = any (array['admin','principal'])
  or payment_plan_id in (
    select pp.id from finance.payment_plans pp
    join finance.invoices i on i.id = pp.invoice_id
    where i.student_id in (select students.id from students where students.auth_user_id = auth.uid())
       or i.student_id in (select parent_links.student_id from parent_links where parent_links.parent_auth_user_id = auth.uid())
  )
);


-- ============================================================================
-- 14. vendor_performance (VIEW, not a table)
-- ============================================================================
create or replace view finance.vendor_performance as
select
  v.id as vendor_id,
  v.name as vendor_name,
  count(po.id) as total_orders,
  coalesce(sum(po.amount), 0::numeric) as total_order_value,
  count(po.id) filter (where po.status = 'paid'::public.payout_status) as orders_paid,
  count(po.id) filter (where po.status = 'rejected'::public.payout_status) as orders_rejected
from finance.vendors v
left join finance.purchase_orders po on po.vendor_id = v.id
group by v.id, v.name;
